// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;

    function setUp() public { c = new StaxLPStaking(address(new __InvMutHandleStub()), address(new __InvMutHandleStub())); }

    function testFuzz_property(address caller, address newDistributor) public {
        vm.assume(caller != address(0));
        address owner = c.owner();

        vm.prank(caller);
        bool ok;
        try c.setRewardDistributor(newDistributor) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: only the owner can successfully change the reward distributor,
        // and when the call succeeds the stored distributor equals the requested address.
        assertTrue(
            ok == (caller == owner) && (!ok || c.rewardDistributor() == newDistributor),
            "setRewardDistributor must succeed only for the owner"
        );
    }
}
contract __InvMutHandleStub {
    function factory() external view returns (address) { return address(this); }
    function createPair(address, address) external view returns (address) { return address(this); }
    function underlying() external view returns (address) { return address(this); }
